{"output":"import WebSocket from "ws";
import { defineDirectAgent, type EvidenceCoverage } from "niceeval/adapter";

type ResearchRequest = {
  reportSource: "local";
  reportType: "research_report";
  tone: "Objective";
};

const evidenceCoverage = {
  events: { status: "partial", reason: "The WebSocket exposes report chunks and progress logs, not a complete normalized event stream." },
  actions: { status: "unavailable", reason: "The WebSocket protocol does not expose paired tool lifecycle events." },
  messages: { status: "complete" },
  usage: { status: "unavailable", reason: "The WebSocket protocol does not expose model token or cost usage." },
  status: { status: "complete" },
  data: { status: "unavailable", reason: "GPT Researcher returns a text report rather than a structured response object." },
} satisfies EvidenceCoverage;

export function gptResearcher(options: { wsUrl: string; request: ResearchRequest }) {
  return defineDirectAgent({
    name: "gpt-researcher-websocket",
    evidenceCoverage,
    async send(input, ctx) {
      ctx.progress({ message: "Connecting to GPT Researcher" });

      return await new Promise((resolve, reject) => {
        const socket = new WebSocket(options.wsUrl);
        const reportChunks: string[] = [];
        let settled = false;

        const finish = (result: Parameters<typeof resolve>[0]) => {
          if (settled) return;
          settled = true;
          socket.close();
          resolve(result);
        };

        const fail = (error: Error) => {
          if (settled) return;
          settled = true;
          socket.terminate();
          reject(error);
        };

        const abort = () => fail(new Error("GPT Researcher request was aborted."));
        ctx.signal.addEventListener("abort", abort, { once: true });

        socket.once("open", () => {
          socket.send(`start ${JSON.stringify({
            task: input.text,
            report_type: options.request.reportType,
            report_source: options.request.reportSource,
            tone: options.request.tone,
            source_urls: [],
            document_urls: [],
            query_domains: [],
            mcp_enabled: false,
            mcp_configs: [],
            mcp_strategy: "fast",
          })}`);
        });

        socket.on("message", (raw) => {
          let event: { type?: string; content?: string; output?: unknown };
          try {
            event = JSON.parse(raw.toString()) as typeof event;
          } catch {
            return;
          }

          if (event.type === "report" && typeof event.output === "string") {
            reportChunks.push(event.output);
            return;
          }
          if (event.type === "logs" && event.content === "error") {
            fail(new Error(typeof event.output === "string" ? event.output : "GPT Researcher returned an error."));
            return;
          }
          if (event.type === "error") {
            fail(new Error(typeof event.output === "string" ? event.output : "GPT Researcher rejected the request."));
            return;
          }
          if (event.type === "path") {
            const report = reportChunks.join("").trim();
            if (!report) {
              fail(new Error("GPT Researcher completed without streaming a report."));
              return;
            }
            finish({
              status: "completed",
              events: [{ type: "message", role: "assistant", text: report }],
            });
          }
        });

        socket.once("error", (error) => fail(new Error(`Could not connect to GPT Researcher at ${options.wsUrl}: ${error.message}`)));
        socket.once("close", () => {
          if (!settled) fail(new Error("GPT Researcher closed the WebSocket before completing the report."));
        });
      });
    },
  });
}
import { defineExperiment } from "niceeval";
import { gptResearcher } from "../agents/gpt-researcher.ts";

export default defineExperiment({
  description: "GPT Researcher local-document baseline",
  agent: gptResearcher({
    wsUrl: process.env.GPTR_WS_URL ?? "ws://localhost:8000/ws",
    request: {
      reportSource: "local",
      reportType: "research_report",
      tone: "Objective",
    },
  }),
  attempts: 1,
  maxConcurrency: 1,
});
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default [
  defineEval({
    description: "answers a commissioning question from the local operations brief",
    async test(t) {
      await t.send("Using the available local operations documents, what calibration temperature is required before commissioning the Ridgeway controller? Explain the result briefly.");
      t.succeeded();
      t.check(t.reply, includes(/18\s*(?:degrees?\s*)?(?:C|Celsius)/i));
    },
  }),
  defineEval({
    description: "does not invent an assignment absent from the local operations brief",
    async test(t) {
      await t.send("Using the available local operations documents, which substation is assigned to controller QX-99?");
      t.succeeded();
      t.check(t.reply, includes(/(?:not|no)\s+(?:listed|provided|available|documented|mentioned|information)|(?:cannot|unable to)\s+(?:determine|find|identify|answer)|do not have/i));
    },
  }),
];
